// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep amount admissible: positive and small enough to send
        vm.assume(amount > 0);
        vm.assume(amount < 1 ether);

        address depositor = address(0xA11CE);
        vm.deal(depositor, amount);

        vm.prank(depositor);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);

        // General rule: exactly one accepted deposit raises depositsCount by exactly one.
        assertTrue(c.depositsCount() == 1);
    }
}
